class Solution {public int[] solve(int[] values){ArrayList<Integer> out=new ArrayList<>();for(int value:values){if(value==0)continue;boolean alive=true;while(alive&&value<0&&!out.isEmpty()&&out.get(out.size()-1)>0){int old=out.get(out.size()-1);if(old<-value)out.remove(out.size()-1);else if(old==-value){out.remove(out.size()-1);alive=false;}else alive=false;}if(alive)out.add(value);}int[] result=new int[out.size()];for(int i=0;i<result.length;i++)result[i]=out.get(i);return result;}}